import type {
  ActivationRepository,
  DeviceRepository,
  LetterRepository,
  LetterRecord,
  Repos,
} from "./types.js";

/// D1-backed repositories. All SQL lives here; the handlers never touch
/// D1 directly. Timestamps are UTC ISO strings generated by the caller.
export function createRepos(db: D1Database): Repos {
  return {
    letters: d1Letters(db),
    activations: d1Activations(db),
    devices: d1Devices(db),
  };
}

function rowToLetter(row: Record<string, unknown>): LetterRecord {
  return {
    seq: Number(row.seq),
    id: String(row.id),
    body: String(row.body),
    created_at: String(row.created_at),
    opened_at: row.opened_at === null ? null : String(row.opened_at),
  };
}

function d1Letters(db: D1Database): LetterRepository {
  return {
    async insertLetter(input) {
      // Dedup happens inside SQL: UNIQUE constraints on id and
      // client_request_id, plus ON CONFLICT return of the old row.
      const existing = await db
        .prepare(
          `SELECT seq, id, body, created_at, opened_at FROM letters
           WHERE id = ? OR (client_request_id IS NOT NULL AND client_request_id = ?)
           LIMIT 1`
        )
        .bind(input.id, input.clientRequestId ?? null)
        .first<Record<string, unknown>>();
      if (existing) {
        return { record: rowToLetter(existing), created: false };
      }
      await db
        .prepare(
          `INSERT INTO letters (id, body, created_at, client_request_id)
           VALUES (?, ?, ?, ?)`
        )
        .bind(input.id, input.body, input.createdAt, input.clientRequestId ?? null)
        .run();
      const inserted = await db
        .prepare(`SELECT seq, id, body, created_at, opened_at FROM letters WHERE id = ?`)
        .bind(input.id)
        .first<Record<string, unknown>>();
      if (!inserted) throw new Error("letter insert returned no row");
      return { record: rowToLetter(inserted), created: true };
    },

    async listLetters(afterSeq, limit) {
      const result = await db
        .prepare(
          `SELECT seq, id, body, created_at, opened_at FROM letters
           WHERE seq > ? ORDER BY seq ASC LIMIT ?`
        )
        .bind(afterSeq, limit)
        .all<Record<string, unknown>>();
      return result.results.map(rowToLetter);
    },

    async findLetterById(id) {
      const row = await db
        .prepare(`SELECT seq, id, body, created_at, opened_at FROM letters WHERE id = ?`)
        .bind(id)
        .first<Record<string, unknown>>();
      return row ? rowToLetter(row) : null;
    },

    async markOpened(id, at) {
      const before = await db
        .prepare(`SELECT opened_at FROM letters WHERE id = ?`)
        .bind(id)
        .first<{ opened_at: string | null }>();
      if (!before) throw new Error("letter not found");
      const alreadyOpened = before.opened_at !== null;
      if (!alreadyOpened) {
        await db
          .prepare(`UPDATE letters SET opened_at = ? WHERE id = ? AND opened_at IS NULL`)
          .bind(at, id)
          .run();
      }
      const row = await db
        .prepare(`SELECT seq, id, body, created_at, opened_at FROM letters WHERE id = ?`)
        .bind(id)
        .first<Record<string, unknown>>();
      if (!row) throw new Error("letter not found");
      return { record: rowToLetter(row), alreadyOpened };
    },
  };
}

function d1Activations(db: D1Database): ActivationRepository {
  return {
    async createCode(codeHash, createdAt, expiresAt) {
      await db
        .prepare(`INSERT INTO activation_codes (code_hash, created_at, expires_at) VALUES (?, ?, ?)`)
        .bind(codeHash, createdAt, expiresAt)
        .run();
    },

    async redeemCode(codeHash, at, deviceId) {
      const row = await db
        .prepare(
          `SELECT created_at, expires_at, used_at FROM activation_codes WHERE code_hash = ?`
        )
        .bind(codeHash)
        .first<{ created_at: string; expires_at: string; used_at: string | null }>();
      if (!row) return { ok: false, reason: "invalid" };
      if (row.used_at !== null) return { ok: false, reason: "used" };
      if (row.expires_at < at) return { ok: false, reason: "expired" };
      const result = await db
        .prepare(
          `UPDATE activation_codes SET used_at = ?, device_id = ? WHERE code_hash = ? AND used_at IS NULL`
        )
        .bind(at, deviceId, codeHash)
        .run();
      // meta.changes: 1 = we won the race; 0 = someone else redeemed first.
      if ((result.meta?.changes ?? 0) === 0) return { ok: false, reason: "used" };
      return { ok: true };
    },

    async listCodes() {
      const result = await db
        .prepare(
          `SELECT code_hash, created_at, expires_at, used_at FROM activation_codes ORDER BY created_at DESC`
        )
        .all<{ code_hash: string; created_at: string; expires_at: string; used_at: string | null }>();
      return result.results;
    },
  };
}

function d1Devices(db: D1Database): DeviceRepository {
  return {
    async createDevice(id, tokenHash, label, createdAt) {
      await db
        .prepare(`INSERT INTO devices (id, token_hash, label, created_at) VALUES (?, ?, ?, ?)`)
        .bind(id, tokenHash, label, createdAt)
        .run();
    },

    async findDeviceByTokenHash(tokenHash) {
      const row = await db
        .prepare(
          `SELECT id, label, created_at, revoked_at FROM devices WHERE token_hash = ?`
        )
        .bind(tokenHash)
        .first<{ id: string; label: string; created_at: string; revoked_at: string | null }>();
      return row ?? null;
    },

    async listDevices() {
      const result = await db
        .prepare(`SELECT id, label, created_at, revoked_at FROM devices ORDER BY created_at ASC`)
        .all<{ id: string; label: string; created_at: string; revoked_at: string | null }>();
      return result.results;
    },

    async revokeDevice(id, at) {
      const result = await db
        .prepare(`UPDATE devices SET revoked_at = ? WHERE id = ? AND revoked_at IS NULL`)
        .bind(at, id)
        .run();
      return (result.meta?.changes ?? 0) > 0;
    },
  };
}
